select t.* from (select pi.id as productId, pi.name as productName, pi.approval_status, pt.name as taskName, to_char(pt.plan_start_time, 'yyyy-MM-dd') as plan_start_time, to_char(pt.plan_end_time, 'yyyy-MM-dd') as plan_end_time, to_char(pt.reality_start_time, 'yyyy-MM-dd') as reality_start_time, to_char(pt.reality_end_time, 'yyyy-MM-dd') as reality_end_time, pt.id as taskId, pt.status, regexp_split_to_table(pt.charge_id,',') as charge_id, regexp_split_to_table(pt.charge_name,',') as charge_name, pt.phase_name, pi2.project_status, case when pt.plan_end_time is null then 0 when to_char(pt.plan_end_time, 'YYYYMMDD') >= to_char(now(), 'YYYYMMDD') then 0 when to_char(now(), 'YYYYMMDD') > to_char(pt.plan_end_time, 'YYYYMMDD') and pt.status != 4 and pt.status != 5 then 1 else 0 end isDelay from product_info pi inner join project_task pt on pi.id = pt.product_id left join project_info pi2 on pi.id = pi2.product_id) t
and
t.charge_id like concat('%',#{item},'%')
and t.productId in
#{item}
and t.status in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
${dto.param}
order by t.charge_id desc, t.plan_end_time asc, t.taskId desc

