select t.* from (select pi.id as productId, pi.name as productName, pi.charge_id, pi.charge_name, pi.approval_status, pi2.project_status, pd.id as skuId, pd.sku_no, to_char(pd.plan_listing_time, 'yyyy-MM-dd') as plan_listing_time, COALESCE(to_char(pd.plan_listing_time, 'YYYYMM'),'') as timeInterval, COALESCE(pi2.project_status,pi.approval_status) as status, case when COALESCE(pi2.project_status,-1) = -1 then 0 else 1 end as isProjectStatus from product_info pi inner join product_detail pd on pi.id = pd.product_id left join project_info pi2 on pi.id = pi2.product_id) t
and
t.charge_id like concat('%',#{item},'%')
and t.productId in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
${dto.param}
order by t.plan_listing_time asc nulls last, t.skuId desc

